// Main game engine: loop, camera, input, rendering orchestration, stats.
// Vanilla TS + canvas for performance; talks to React via callbacks.

import { World, CELL, MAT_EMPTY, SKY_ROWS } from './world'
import { buildLevel, LoadProgress, LevelData } from './loader'
import { buildBackgrounds, BgBundle } from './backgrounds'
import { Player, PHYS, InputState } from './player'
import { WEAPONS, WeaponDef, WeaponEntities, newWeaponEntities, fireWeapon, throwGrenade, stepEntities, drawEntities, GRENADE, explodeAt, getWeaponIcon, spawnBullet } from './weapons'
import { drawStickman, WEAPON_ICONS, buildSpriteCanvas } from './sprites'
import { sound } from './sound'

export type GameStats = {
  pct: number
  pctMax: number
  letters: number
  blocks: number
  explosions: number
  shots: number
  time: number
  done: boolean
  weapon: number
  weaponName: string
  weaponNameEn: string
  fps: number
  site: string
  droneBattery: number
  droneCd: number
  hasDrone: boolean
  characterName: string
}

export type MilestoneInfo = {
  pct: number
  titleAr: string
  titleEn: string
}

export type EngineCallbacks = {
  onProgress: LoadProgress
  onStats: (s: GameStats) => void
  onComplete: (s: { letters: number; blocks: number; explosions: number; shots: number; time: number }) => void
  onPauseRequest: () => void
  onMilestone?: (m: MilestoneInfo) => void
}

export type StartOptions = {
  url: string // 'demo' or website url
  bgTheme: string
}

const LAYOUT_W = 1080

import { ConfigManager } from './engineConfig'
import { drawCharacter } from './sprites'

export class DestroyEngine {
  private canvas: HTMLCanvasElement | null = null
  private ctx: CanvasRenderingContext2D | null = null
  private raf = 0
  private last = 0
  private acc = 0
  private running = false
  private paused = false

  world = new World()
  player: Player | null = null
  es: WeaponEntities = newWeaponEntities()
  private bg: BgBundle | null = null
  private camX = 0
  private camY = 0
  private prevCamX = 0
  private prevCamY = 0
  private shake = 0
  private shakeX = 0
  private shakeY = 0
  private viewW = 800
  private viewH = 600
  private dpr = 1

  private input: InputState = {
    left: false,
    right: false,
    jump: false,
    jumpPressed: false,
    down: false,
    fire: false,
    alt: false,
    altPressed: false,
    aimX: 0,
    aimY: 0,
    wheel: 0,
  }

  private keysDown = new Set<string>()
  private statsT = 0
  private pctMax = 0
  private startTime = 0
  private done = false
  private fps = 60
  private fpsAcc = 0
  private fpsN = 0
  private site = ''
  private weaponNameT = 0
  private mouseInside = true
  private clientMouseX = 0
  private clientMouseY = 0
  private hitStopTimer = 0
  private trailSpawnTimer = 0
  private backdropCanvas: HTMLCanvasElement | null = null

  cb: EngineCallbacks
  private opts: StartOptions | null = null

  constructor(cb: EngineCallbacks) {
    this.cb = cb
    this.loop = this.loop.bind(this)
  }

  setCanvas(canvas: HTMLCanvasElement) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')
    this.resize()
  }

  resize() {
    if (!this.canvas) return
    const rect = this.canvas.getBoundingClientRect()
    this.dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1))
    this.viewW = Math.max(320, Math.floor(rect.width))
    this.viewH = Math.max(240, Math.floor(rect.height))
    this.canvas.width = Math.floor(this.viewW * this.dpr)
    this.canvas.height = Math.floor(this.viewH * this.dpr)
  }

  async start(opts: StartOptions) {
    this.opts = opts
    this.site = opts.url === 'demo' ? 'غير قابل للتدمير' : opts.url.replace(/^https?:\/\//, '')

    // 1) fetch html
    this.cb.onProgress('جلب الصفحة…', 0.06)
    const resp = await fetch(`/api/page?url=${encodeURIComponent(opts.url)}`)
    if (!resp.ok) {
      let msg = 'تعذّر تحميل الموقع.'
      try {
        const j = await resp.json()
        if (j.error) msg = j.error
      } catch {
        /* noop */
      }
      throw new Error(msg)
    }
    const html = await resp.text()

    // 2) build level
    const level = await buildLevel(html, opts.url === 'demo' ? 'https://demo.local/' : `https://${opts.url.replace(/^https?:\/\//, '')}`, LAYOUT_W, (m, p) => {
      this.cb.onProgress(m, p)
    })

    await this.startWithLevel(level, this.site, opts.bgTheme)
  }

  async startWithLevel(level: LevelData, siteTitle: string = 'الموقع الحالي', bgTheme: string = 'grid') {
    this.done = false
    this.paused = false
    this.pctMax = 0
    this.milestonesPassed.clear()
    this.es = newWeaponEntities()
    this.site = siteTitle
    sound.ensure()

    this.backdropCanvas = level.backdropCanvas || null

    // 3) init world + player (extra sky rows above the page, like the original)
    const pageGW = Math.ceil(level.W / CELL)
    const pageGH = Math.ceil(level.H / CELL)
    const skyPx = SKY_ROWS * CELL
    const bottomPx = 130 // breathing room below the page so the player is visible above the HUD
    this.world.onElementGone = undefined
    this.hitStopTimer = 0
    this.world.onShatter = (b, force) => {
      // Impact hit-stop for visceral combat feedback on heavy destruction
      if (b.mass > 350 || force > 450) {
        this.hitStopTimer = Math.min(0.035, 0.015 + b.mass / 35000)
        this.shake = Math.max(this.shake, Math.min(10, 3 + force / 90))
      }
    }
    this.world.onPortalShatter = (_wx, _wy) => {
      if (this.player) {
        this.player.jetFuel = Math.min(1.0, this.player.jetFuel + 0.35)
        sound.labBeep(true)
      }
    }
    this.world.init(level.W, level.H + skyPx + bottomPx)
    if (level.bodies && level.bodies.length > 0) {
      this.world.loadBodies(level.bodies, level.W, level.H, skyPx)
    } else {
      this.world.loadFromLoader(level.colors, level.owners, level.elements, pageGW, pageGH)
    }
    this.bg = buildBackgrounds(Math.max(900, this.viewW), Math.max(700, this.viewH), bgTheme)

    // spawn player: topmost solid surface or platform near page center with headroom
    let spawnX = level.W / 2
    let spawnY = skyPx + 20

    if (level.bodies && level.bodies.length > 0) {
      // Find candidate landing surfaces near horizontal center (within center 60% of page)
      const minX = level.W * 0.2
      const maxX = level.W * 0.8
      let bestY = Infinity
      let bestX = spawnX

      for (let i = 0; i < this.world.bodies.length; i++) {
        const b = this.world.bodies[i]
        if (!b.anchored || b.destroyed) continue
        if (b.w < 30 || b.h < 8) continue // skip tiny slivers
        if (b.x + b.w < minX || b.x > maxX) continue // must be reasonably near center

        // Candidate landing spot: top-center of this body
        const testX = Math.max(b.x + 16, Math.min(b.x + b.w - 16, level.W / 2))
        const testY = b.y - 1 // right above the top surface

        // Must be higher (smaller Y) than our current best, and below the sky
        if (testY < bestY && testY >= skyPx) {
          // Check headroom: ensure at least 44px of vertical clearance above
          let headroomClear = true
          for (let dy = 2; dy <= 44; dy += 6) {
            if (this.world.solidAtWorld(testX, testY - dy)) {
              headroomClear = false
              break
            }
          }
          if (headroomClear) {
            bestY = testY
            bestX = testX
          }
        }
      }

      if (bestY < Infinity) {
        spawnX = bestX
        spawnY = bestY
      }
    } else if (this.world.mat) {
      // Fallback for legacy loader
      outer: for (let cy = 2; cy < this.world.GH - 4; cy++) {
        for (let cx = Math.floor(this.world.GW / 4); cx < this.world.GW - 4; cx += 2) {
          if (this.world.mat[this.world.idx(cx, cy)] !== MAT_EMPTY && this.world.mat[this.world.idx(cx, cy - 1)] === MAT_EMPTY) {
            spawnX = cx * CELL
            spawnY = cy * CELL - 1
            break outer
          }
        }
      }
    }
    // Ensure spawn area is clear: if obstructed by solid obstacles, safely raise spawn point into open air
    let clear = true
    for (let dy = 1; dy <= 42; dy += 4) {
      for (let dx = -12; dx <= 12; dx += 4) {
        if (this.world.solidAtWorld(spawnX + dx, spawnY - dy)) {
          clear = false
          break
        }
      }
      if (!clear) break
    }
    if (!clear) {
      let testY = spawnY
      while (testY > skyPx && !clear) {
        testY -= 8
        clear = true
        for (let dy = 1; dy <= 42; dy += 4) {
          for (let dx = -12; dx <= 12; dx += 4) {
            if (this.world.solidAtWorld(spawnX + dx, testY - dy)) {
              clear = false
              break
            }
          }
          if (!clear) break
        }
      }
      spawnY = Math.max(skyPx + 20, testY)
    }
    this.player = new Player(spawnX, spawnY)
    this.player.weaponIdx = 0
    this.camX = Math.max(0, Math.min(level.W - this.viewW, spawnX - this.viewW / 2))
    this.camY = Math.max(0, spawnY - this.viewH / 2)
    this.startTime = performance.now()
    this.done = false

    this.cb.onProgress('اكتمل!', 1)
    ;(window as unknown as { __daw: DestroyEngine }).__daw = this
    sound.start()
    this.running = true
    this.last = performance.now()
    if (!this.raf) this.raf = requestAnimationFrame(this.loop)
  }

  stop() {
    this.running = false
    if (this.raf) {
      cancelAnimationFrame(this.raf)
      this.raf = 0
    }
    this.player = null
  }

  setPaused(p: boolean) {
    this.paused = p
    if (!p) this.last = performance.now()
  }

  setBgTheme(theme: string) {
    this.bg = buildBackgrounds(Math.max(900, this.viewW), Math.max(700, this.viewH), theme)
  }

  // ---- input plumbing (called by React component) ----
  onKey(e: KeyboardEvent, down: boolean) {
    const k = e.key.toLowerCase()
    if (down) {
      if (this.keysDown.has(k)) return
      this.keysDown.add(k)
    } else this.keysDown.delete(k)
    switch (k) {
      case 'a':
      case 'arrowleft':
        this.input.left = down
        break
      case 'd':
      case 'arrowright':
        this.input.right = down
        break
      case ' ':
      case 'w':
      case 'arrowup':
        if (down && !this.input.jump) this.input.jumpPressed = true
        this.input.jump = down
        e.preventDefault()
        break
      case 's':
      case 'arrowdown':
        this.input.down = down
        break
      case '1':
      case '2':
      case '3':
      case '4':
      case '5':
      case '6':
      case '7':
      case '8':
      case '9':
      case '0': {
        if (down) {
          const n = k === '0' ? 9 : parseInt(k) - 1
          this.selectWeapon(n)
        }
        break
      }
      case 'q':
        if (down) this.selectWeapon(((this.player?.weaponIdx ?? 0) - 1 + WEAPONS.length) % WEAPONS.length)
        break
      case 'e':
        if (down) this.selectWeapon(((this.player?.weaponIdx ?? 0) + 1) % WEAPONS.length)
        break
      case 'escape':
      case 'p':
        if (down) this.cb.onPauseRequest()
        break
    }
  }

  // Window lost focus: release all active inputs to prevent keys sticking
  onBlur() {
    this.keysDown.clear()
    this.input.left = false
    this.input.right = false
    this.input.jump = false
    this.input.down = false
    this.input.fire = false
    this.input.alt = false
  }

  selectWeapon(n: number) {
    if (!this.player || n === this.player.weaponIdx || n < 0 || n >= WEAPONS.length) return
    this.player.weaponIdx = n
    this.player.switchT = 0
    this.player.cooldown = 0.12
    sound.switch(0)
    this.weaponNameT = 1.4
  }

  onMouseMove(x: number, y: number) {
    this.clientMouseX = x
    this.clientMouseY = y
    this.input.aimX = x + this.camX
    this.input.aimY = y + this.camY
    this.mouseInside = true
  }

  onMouseDown(btn: number) {
    if (btn === 0) {
      this.input.fire = true
    } else if (btn === 2) {
      this.input.altPressed = true
      this.input.alt = true
    }
  }

  onMouseUp(btn: number) {
    if (btn === 0) this.input.fire = false
    else if (btn === 2) this.input.alt = false
  }

  onWheel(dy: number) {
    if (!this.player) return
    const dir = dy > 0 ? 1 : -1
    this.selectWeapon((this.player.weaponIdx + dir + WEAPONS.length) % WEAPONS.length)
  }

  onTouchAim(x: number, y: number, down: boolean) {
    this.clientMouseX = x
    this.clientMouseY = y
    this.input.aimX = x + this.camX
    this.input.aimY = y + this.camY
    this.input.fire = down
  }

  // ---- main loop ----
  private loop(now: number) {
    this.raf = 0
    if (!this.running) return
    this.raf = requestAnimationFrame(this.loop)
    let dt = (now - this.last) / 1000
    this.last = now
    if (this.paused) return
    if (dt > 0.1) dt = 0.1

    if (this.hitStopTimer > 0) {
      this.hitStopTimer -= dt
      if (this.shake > 0) {
        this.shakeX = (Math.random() - 0.5) * this.shake * 34
        this.shakeY = (Math.random() - 0.5) * this.shake * 34
      }
      this.render()
      return
    }

    this.fpsAcc += dt
    this.fpsN++
    if (this.fpsAcc >= 0.5) {
      this.fps = Math.round(this.fpsN / this.fpsAcc)
      this.fpsAcc = 0
      this.fpsN = 0
    }

    this.prevCamX = this.camX
    this.prevCamY = this.camY
    this.acc += dt
    const STEP = 1 / 120
    let steps = 0
    while (this.acc >= STEP && steps < 8) {
      this.stepGame(STEP)
      this.acc -= STEP
      steps++
    }
    this.render()
    this.acc = Math.min(this.acc, 0.1)

    // stats to react ~10/s
    this.statsT += dt
    if (this.statsT > 0.1) {
      this.statsT = 0
      this.emitStats()
    }
  }

  private stepGame(dt: number) {
    const world = this.world
    const p = this.player
    if (!p) return

    // Keep aim synced with camera even when mouse is stationary
    this.input.aimX = this.clientMouseX + this.camX
    this.input.aimY = this.clientMouseY + this.camY

    // consume one-shot inputs
    const inp: InputState = { ...this.input, jumpPressed: this.input.jumpPressed, altPressed: this.input.altPressed }
    this.input.jumpPressed = false
    this.input.altPressed = false
    if (this.input.wheel !== 0) {
      this.onWheel(this.input.wheel)
      this.input.wheel = 0
    }

    p.step(world, inp, dt)

    // firing
    const w = WEAPONS[p.weaponIdx]
    const cfg = ConfigManager.get().getConfig()
    const wTune = cfg.weapons[w.id] || { cooldownMul: 1 }

    if (inp.fire && p.cooldown <= 0 && !this.done) {
      if (w.kind === 'drone') {
        // Deploy drone if not active
        if ((!this.es.drone || this.es.drone.state === 2) && this.es.droneCd <= 0) {
          this.es.drone = { x: p.x + p.facing * 24, y: p.y - 64, vx: 0, vy: 0, battery: 14, maxBattery: 14, state: 0, fireT: 0, rampK: 0, lowBeepT: 0 }
          sound.droneBeep(0)
          this.weaponNameT = 1.2
        }
        // Player shoots plasma bolt in tandem with the drone
        const mzX = p.x + Math.cos(p.aim) * 26
        const mzY = p.y - 34 + Math.sin(p.aim) * 26
        spawnBullet(this.es, mzX, mzY, Math.cos(p.aim) * 2600, Math.sin(p.aim) * 2600, 18, 4, '#7ff3ff')
        sound.shot('drone', 0.8, 0)
        p.shots++
        p.flashT = 0.05
        p.bloomT = 0.1
        p.kickRotV -= 0.5
        p.cooldown = 0.22 * (wTune.cooldownMul ?? 1)
        this.fireHeld = true
      } else if (w.auto || !this.fireHeld) {
        const pan = 0
        fireWeapon(
          world,
          this.es,
          w,
          p.x,
          p.y - 34,
          p.aim,
          pan,
          (s) => (this.shake = Math.max(this.shake, s)),
          (vx, vy) => p.impulse(vx, vy),
          () => {
            p.shots++
            p.flashT = 0.06
            p.bloomT = 0.1
            p.kickRotV -= w.kick * 0.35
          },
          this.input.aimX,
          this.input.aimY
        )
        p.cooldown = w.cooldown * (wTune.cooldownMul ?? 1)
        this.fireHeld = true
      }
    }
    if (!inp.fire) this.fireHeld = false

    // railgun charge sound on select
    if (p.chargeT <= 0 && p.weaponIdx === 4 && this.fireHeld && p.cooldown > 0.8) {
      // noop
    }

    // grenade / alt fire (RMB)
    if (inp.altPressed && !this.done) {
      const d = this.es.drone
      // If holding drone controller specifically and drone is active, RMB dive-bombs into target
      if (w.kind === 'drone' && d && d.state === 0 && Math.hypot(d.x - p.x, d.y - p.y) < 900) {
        d.state = 1
        d.vx = (this.input.aimX - d.x) * 1.6
        d.vy = Math.max(140, (this.input.aimY - d.y) * 1.6)
        sound.droneBeep(0)
      } else if (p.grenadeCd <= 0) {
        // For ALL OTHER WEAPONS, RMB throws grenades freely without disturbing the drone
        throwGrenade(
          world,
          this.es,
          p.x + Math.cos(p.aim) * 20,
          p.y - 34 + Math.sin(p.aim) * 20,
          p.aim,
          GRENADE.speed,
          this.input.aimX,
          this.input.aimY
        )
        p.grenadeCd = GRENADE.cooldown
        p.throwT = 0.22
      }
      this.input.alt = false
    }

    // step entities
    stepEntities(world, this.es, dt, p.x, p.y, { x: this.input.aimX, y: this.input.aimY })

    // drone auto-fire toward aim
    const d = this.es.drone
    if (d && d.state === 0 && this.input.fire && d.battery > 0) {
      d.fireT = (d.fireT ?? 0) - dt
      if (d.fireT <= 0) {
        d.fireT = 0.09
        const dx = this.input.aimX - d.x
        const dy = this.input.aimY - d.y
        const dd = Math.hypot(dx, dy) || 1
        void dd
        const a = Math.atan2(dy, dx) + (Math.random() - 0.5) * 0.1
        const sp = 2700
        spawnBullet(this.es, d.x, d.y, Math.cos(a) * sp, Math.sin(a) * sp, 16, 5, '#7ff3ff')
        sound.shot('drone', 0.5, 0)
        d.battery -= 0.12
        p.shots++
      }
    }

    // Player trail particles based on ConfigManager character.trail
    const charCfg = ConfigManager.get().getConfig().character
    const pSpeed = Math.hypot(p.vx, p.vy)
    const isMovingFast = pSpeed > 220
    const isSpecialAction = p.jetOn || p.flipT >= 0 || (p.skidT && p.skidT > 0)

    if (isMovingFast || isSpecialAction) {
      this.trailSpawnTimer -= dt
      if (this.trailSpawnTimer <= 0) {
        this.trailSpawnTimer = p.jetOn ? 0.025 : 0.04
        const trailType = charCfg.trail ?? 'sparks'
        const spawnX = p.x - p.facing * 8 + (Math.random() - 0.5) * 6
        const spawnY = p.y - 20 + (Math.random() - 0.5) * 12

        switch (trailType) {
          case 'sparks': {
            world.spawnParticle({
              x: spawnX,
              y: spawnY,
              vx: -p.vx * 0.2 + (Math.random() - 0.5) * 60,
              vy: -p.vy * 0.2 + (Math.random() - 0.5) * 60,
              life: 0.35,
              max: 0.35,
              kind: 'spark',
              color: Math.random() < 0.5 ? '#fbbf24' : '#ffd23d',
              size: 2 + Math.random() * 2,
            })
            break
          }
          case 'smoke': {
            world.spawnParticle({
              x: spawnX,
              y: spawnY,
              vx: -p.vx * 0.15 + (Math.random() - 0.5) * 30,
              vy: -20 + (Math.random() - 0.5) * 30,
              life: 0.4,
              max: 0.4,
              kind: 'smoke',
              color: 'rgba(148, 163, 184, 0.5)',
              size: 3 + Math.random() * 3,
            })
            break
          }
          case 'void': {
            world.spawnParticle({
              x: spawnX,
              y: spawnY,
              vx: -p.vx * 0.1 + (Math.random() - 0.5) * 40,
              vy: -p.vy * 0.1 + (Math.random() - 0.5) * 40,
              life: 0.35,
              max: 0.35,
              kind: 'spark',
              color: Math.random() < 0.6 ? '#a855f7' : '#06b6d4',
              size: 2.5 + Math.random() * 2,
            })
            break
          }
          case 'rainbow': {
            const hue = (Date.now() * 0.4) % 360
            world.spawnParticle({
              x: spawnX,
              y: spawnY,
              vx: -p.vx * 0.2 + (Math.random() - 0.5) * 50,
              vy: -p.vy * 0.2 + (Math.random() - 0.5) * 50,
              life: 0.4,
              max: 0.4,
              kind: 'spark',
              color: `hsl(${hue}, 100%, 65%)`,
              size: 2.5 + Math.random() * 2,
            })
            break
          }
        }
      }
    }

    world.step(dt)

    // camera follow
    const targetX = p.x - this.viewW / 2 + Math.cos(p.aim) * 40
    const targetY = p.y - this.viewH / 2 - 40 + Math.sin(p.aim) * 24
    const k = 1 - Math.exp(-dt / 0.09)
    this.camX += (targetX - this.camX) * k
    this.camY += (targetY - this.camY) * k
    this.camX = Math.max(0, Math.min(Math.max(0, world.W - this.viewW), this.camX))
    this.camY = Math.max(0, Math.min(Math.max(0, world.H - this.viewH), this.camY))

    // shake
    if (this.shake > 0) {
      this.shake = Math.max(0, this.shake - dt * 2.2)
      this.shakeX = (Math.random() - 0.5) * this.shake * 34
      this.shakeY = (Math.random() - 0.5) * this.shake * 34
    } else {
      this.shakeX = 0
      this.shakeY = 0
    }

    if (this.weaponNameT > 0) this.weaponNameT -= dt

    // completion & milestone checks
    const pct = world.destroyedPct()
    if (pct > this.pctMax) this.pctMax = pct

    const milestones = [
      { pct: 0.25, titleAr: 'بداية السحق! 25%', titleEn: '25% DEMOLISHED!' },
      { pct: 0.50, titleAr: 'سقوط نصف الموقع! 50%', titleEn: '50% CRUSHED!' },
      { pct: 0.75, titleAr: 'تدمير شامل هائل! 75%', titleEn: '75% HEAVY DAMAGE!' },
      { pct: 0.90, titleAr: 'الإبادة وشيكة! 90%', titleEn: '90% CRITICAL STATUS!' },
      { pct: 0.99, titleAr: 'محو تام للموقع! 100%', titleEn: '100% TOTAL ANNIHILATION!' },
    ]
    for (const m of milestones) {
      if (pct >= m.pct && !this.milestonesPassed.has(m.pct)) {
        this.milestonesPassed.add(m.pct)
        sound.milestone()
        this.cb.onMilestone?.(m)
      }
    }

    if (!this.done && pct >= 0.99) {
      this.done = true
      const time = Math.round((performance.now() - this.startTime) / 1000)
      sound.complete()
      setTimeout(() => {
        this.cb.onComplete({
          letters: world.lettersPopped,
          blocks: world.blocksBroken,
          explosions: world.explosions,
          shots: p.shots,
          time,
        })
      }, 900)
    }
  }

  private fireHeld = false
  private milestonesPassed = new Set<number>()

  private emitStats() {
    const world = this.world
    const p = this.player
    if (!p) return
    const w = WEAPONS[p.weaponIdx]
    const charCfg = ConfigManager.get().getConfig().character
    this.cb.onStats({
      pct: world.destroyedPct(),
      pctMax: this.pctMax,
      letters: world.lettersPopped,
      blocks: world.blocksBroken,
      explosions: world.explosions,
      shots: p.shots,
      time: (performance.now() - this.startTime) / 1000,
      done: this.done,
      weapon: p.weaponIdx,
      weaponName: w.nameAr,
      weaponNameEn: w.nameEn,
      fps: this.fps,
      site: this.site,
      droneBattery: this.es.drone?.battery ?? 0,
      droneCd: this.es.droneCd,
      hasDrone: !!this.es.drone && this.es.drone.state !== 2,
      characterName: charCfg.name,
    })
  }

  // ---- render ----
  private render() {
    const ctx = this.ctx
    if (!ctx || !this.player) return
    const world = this.world
    ctx.save()
    ctx.scale(this.dpr, this.dpr)
    ctx.imageSmoothingEnabled = true
    ctx.imageSmoothingQuality = 'high'

    const STEP = 1 / 120
    const alpha = Math.max(0, Math.min(1, this.acc / STEP))
    const renderCamX = this.prevCamX + (this.camX - this.prevCamX) * alpha
    const renderCamY = this.prevCamY + (this.camY - this.prevCamY) * alpha

    const camX = renderCamX + this.shakeX
    const camY = renderCamY + this.shakeY

    // background parallax
    if (this.bg) this.bg.draw(ctx, camX, camY, this.viewW, this.viewH, world.H)
    else {
      ctx.fillStyle = '#000000'
      ctx.fillRect(0, 0, this.viewW, this.viewH)
    }

    // Webpage backdrop sheet (clean HTML page canvas with shadow & borders)
    if (this.backdropCanvas) {
      const pageX = 0 - camX
      const pageY = SKY_ROWS * CELL - camY
      ctx.save()
      ctx.shadowColor = 'rgba(0, 0, 0, 0.42)'
      ctx.shadowBlur = 28
      ctx.shadowOffsetY = 12
      ctx.drawImage(this.backdropCanvas, pageX, pageY)
      ctx.restore()
    }

    // world pixels (interactive & destructible elements)
    world.draw(ctx, camX, camY, this.viewW, this.viewH)

    // entities below player
    drawEntities(ctx, world, this.es, camX, camY)

    // player (smoothly interpolated position)
    const p = this.player
    const curW = WEAPONS[p.weaponIdx]
    const icon = getWeaponIcon(curW.id)
    const spr = WEAPON_ICONS[curW.id]
    const renderPx = p.prevX !== undefined ? p.prevX + (p.x - p.prevX) * alpha : p.x
    const renderPy = p.prevY !== undefined ? p.prevY + (p.y - p.prevY) * alpha : p.y
    const kx = renderPx - camX
    const ky = renderPy - camY
    const charCfg = ConfigManager.get().getConfig().character

    const wa = spr?.anchor
      ? { dx: spr.anchor.x * 2, dy: spr.anchor.y * 2 }
      : icon
      ? { dx: Math.floor(icon.width * 0.28), dy: Math.floor(icon.height * 0.55) }
      : null

    drawCharacter(ctx, kx, ky, {
      facing: p.facing,
      runPhase: p.runPhase,
      grounded: p.grounded,
      jetOn: p.jetOn && p.jetK > 0.4,
      flipT: p.flipT,
      tumble: p.tumble,
      vy: p.vy,
      vx: p.vx,
      aim: p.aim + (p.facing === 1 ? p.kickRot : -p.kickRot),
      weapon: icon,
      weaponAnchor: wa,
      jetK: p.jetK,
      squash: p.landT > 0 ? Math.sin((p.landT / 0.2) * Math.PI) * 0.12 : 0,
      switchT: p.switchT,
      skidT: p.skidT,
      throwT: p.throwT,
      bloomT: p.bloomT,
      skin: charCfg.skin,
      colors: {
        head: charCfg.headColor,
        body: charCfg.bodyColor,
        accent: charCfg.accentColor,
        outline: charCfg.outlineColor,
        thruster: charCfg.thrusterColor,
      },
    })

    // Jetpack fuel gauge above head when discharging
    if (p.jetFuel < 0.999) {
      ctx.fillStyle = 'rgba(0,0,0,0.55)'
      ctx.fillRect(kx - 13, ky - 66, 26, 4)
      ctx.fillStyle = p.jetFuel < 0.25 ? '#f2561d' : '#ffd23d'
      ctx.fillRect(kx - 12, ky - 65, 24 * p.jetFuel, 2)
    }

    // particles on top
    world.drawParticles(ctx, camX, camY)

    // Grenade Ballistic Trajectory Arc & Impact Reticle
    const isGrenadeReady = p.grenadeCd <= 0
    const startX = renderPx + Math.cos(p.aim) * 20
    const startY = renderPy - 34 + Math.sin(p.aim) * 20
    const targetX = this.input.aimX
    const targetY = this.input.aimY

    const g = 2000
    const tDx = targetX - startX
    const tDy = targetY - startY
    const tDist = Math.hypot(tDx, tDy)
    const clampedDist = Math.min(750, Math.max(40, tDist))
    const T = Math.min(1.1, Math.max(0.35, Math.sqrt((2 * clampedDist) / g) * 1.1))
    const throwVx = Math.max(-800, Math.min(800, (tDx / (tDist || 1)) * (clampedDist / T)))
    const throwVy = Math.max(-950, Math.min(400, (tDy - 0.5 * g * T * T) / T))

    ctx.save()
    const arcSteps = 16
    for (let i = 1; i <= arcSteps; i++) {
      const tArc = (i / arcSteps) * T
      const arcX = startX + throwVx * tArc - camX
      const arcY = startY + throwVy * tArc + 0.5 * g * tArc * tArc - camY
      const alphaVal = (i / arcSteps) * (isGrenadeReady ? 0.75 : 0.25)
      ctx.fillStyle = isGrenadeReady ? `rgba(251, 191, 36, ${alphaVal})` : `rgba(148, 163, 184, ${alphaVal})`
      ctx.beginPath()
      ctx.arc(arcX, arcY, isGrenadeReady ? 2.2 : 1.4, 0, Math.PI * 2)
      ctx.fill()
    }

    // Impact target reticle
    const endX = startX + throwVx * T - camX
    const endY = startY + throwVy * T + 0.5 * g * T * T - camY
    ctx.strokeStyle = isGrenadeReady ? 'rgba(251, 191, 36, 0.85)' : 'rgba(148, 163, 184, 0.35)'
    ctx.lineWidth = 1.5
    ctx.beginPath()
    ctx.arc(endX, endY, 7 + Math.sin(Date.now() * 0.009) * 2, 0, Math.PI * 2)
    ctx.stroke()
    ctx.restore()

    // crosshair (dark outline + white core for visibility on any surface)
    const mx = this.clientMouseX
    const my = this.clientMouseY
    ctx.save()
    ctx.lineCap = 'butt'
    for (const pass of [0, 1]) {
      ctx.strokeStyle = pass === 0 ? 'rgba(0,0,0,0.85)' : 'rgba(255,255,255,0.95)'
      ctx.lineWidth = pass === 0 ? 4 : 1.6
      ctx.beginPath()
      ctx.moveTo(mx - 10, my)
      ctx.lineTo(mx - 3, my)
      ctx.moveTo(mx + 3, my)
      ctx.lineTo(mx + 10, my)
      ctx.moveTo(mx, my - 10)
      ctx.lineTo(mx, my - 3)
      ctx.moveTo(mx, my + 3)
      ctx.lineTo(mx, my + 10)
      ctx.stroke()
    }

    // Circular Grenade Cooldown Meter around Crosshair
    const cdProgress = p.grenadeCd > 0 ? 1 - p.grenadeCd / GRENADE.cooldown : 1
    ctx.lineWidth = 2
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.45)'
    ctx.beginPath()
    ctx.arc(mx, my, 13, 0, Math.PI * 2)
    ctx.stroke()

    ctx.strokeStyle = isGrenadeReady ? '#fbbf24' : '#64748b'
    ctx.beginPath()
    ctx.arc(mx, my, 13, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * cdProgress)
    ctx.stroke()
    if (isGrenadeReady) {
      ctx.fillStyle = '#ffd23d'
      ctx.beginPath()
      ctx.arc(mx, my - 13, 2, 0, Math.PI * 2)
      ctx.fill()
    }
    ctx.restore()

    // muzzle flash (aligned with interpolated player shoulder position)
    if (p.flashT > 0 && WEAPONS[p.weaponIdx].kind !== 'wand') {
      const fa = p.aim
      const fx = renderPx + Math.cos(fa) * 32 - camX
      const fy = renderPy - 34 + Math.sin(fa) * 32 - camY
      ctx.fillStyle = '#fff3a6'
      ctx.beginPath()
      ctx.arc(fx, fy, 7 + Math.random() * 5, 0, Math.PI * 2)
      ctx.fill()
      ctx.fillStyle = '#ffffff'
      ctx.beginPath()
      ctx.arc(fx, fy, 3.5, 0, Math.PI * 2)
      ctx.fill()
    }

    ctx.restore()
  }
}

export const weaponList = WEAPONS
export const weaponIcons = WEAPON_ICONS
export const buildIcon = buildSpriteCanvas
export type { WeaponDef }
